#!/usr/bin/env bash
# ═════════════════════════════════════════════════════════════════════════════
#  🔥 ALYAN WEBPANEL — Ultra-Fast Real-Time VLESS & Socket Bridge Update
#  1) Cleans temporary cache, leftover rules & test monitors
#  2) Applies Wire-Speed BBR + fq + 32MB TCP Autotuning
#  3) Deploys Nginx Edge Router & HAProxy Multi-Protocol Templates (127.0.0.1:8885 Bridge)
#  4) Deploys Clean Xray Core Multi-Protocol Engine (20001-20005)
#  5) Deploys Alyan Xray Real-Time Socket Bridge (1-2s instant disconnect + Subnet CGNAT Dedup)
#  6) Deploys Real-Time Socket Guard Engine (Replaces Zeta delay with Instant Socket Detection)
#  7) Updates alyan-ctl & tunes Webpanel Zero-Lag Live Sync (500ms frontend / 0.8s cache)
#  8) Syncs Xray, reloads HAProxy/Nginx & restarts services cleanly
# ═════════════════════════════════════════════════════════════════════════════
set -e

if [[ "${EUID:-$(id -u)}" -ne 0 ]]; then
  echo "Run as root: sudo bash update-vless.sh"
  exit 1
fi

echo "════════════════════════════════════════════════════════════════════"
echo " 🔥 ALYAN WEBPANEL — Ultra-Fast Real-Time VLESS Socket Update"
echo "════════════════════════════════════════════════════════════════════"

# ─── [1/8] Clean Leftover Rules, UDP Gateways, Temp Cache & Old Monitors ─────
echo "[1/8] Cleaning temporary cache, leftover rules & test units..."
for svc in alyan-live-monitor udpgw badvpn-udpgw alyan-udpgw; do
  systemctl stop "$svc" 2>/dev/null || true
  systemctl disable "$svc" 2>/dev/null || true
  rm -f "/etc/systemd/system/${svc}.service" 2>/dev/null || true
done
pkill -9 -f "udpgw" 2>/dev/null || true
pkill -9 -f "alyan-live-monitor" 2>/dev/null || true

rm -rf /tmp/alyan* /tmp/xray* /tmp/vless* /tmp/vps_* /tmp/test_* /var/tmp/alyan* /run/alyan-guard.lock /run/alyan-live.tmp /opt/alyan/services/guard/*.bak* /opt/alyan/**/__pycache__ 2>/dev/null || true
truncate -s 0 /var/log/xray/error.log 2>/dev/null || true
journalctl --vacuum-size=10M >/dev/null 2>&1 || true

# ─── [2/8] Apply Wire-Speed BBR + fq + 32MB Autotuning ───────────────────────
echo "[2/8] Applying clean BBR + fq + 32MB autotuning kernel profile..."
modprobe tcp_bbr 2>/dev/null || true

cat <<'EOF_SYSCTL' > /etc/sysctl.d/99-alyan-turbo.conf
# Alyan Webpanel — Native Wire-Speed + Stable Ping Kernel Profile
fs.file-max = 2097152
net.core.default_qdisc = fq
net.ipv4.tcp_congestion_control = bbr
net.core.somaxconn = 65535
net.core.netdev_max_backlog = 65536
net.core.optmem_max = 33554432
net.core.rmem_default = 262144
net.core.wmem_default = 262144
net.core.rmem_max = 33554432
net.core.wmem_max = 33554432
net.ipv4.tcp_rmem = 4096 131072 33554432
net.ipv4.tcp_wmem = 4096 131072 33554432
net.ipv4.tcp_notsent_lowat = 131072
net.ipv4.tcp_autocorking = 0
net.ipv4.tcp_thin_linear_timeouts = 1
net.ipv4.tcp_slow_start_after_idle = 0
net.ipv4.tcp_mtu_probing = 0
net.ipv4.tcp_fastopen = 3
net.ipv4.tcp_tw_reuse = 1
net.ipv4.tcp_fin_timeout = 10
net.ipv4.tcp_retries2 = 15
net.ipv4.tcp_max_syn_backlog = 65536
net.ipv4.tcp_max_tw_buckets = 2000000
net.ipv4.ip_local_port_range = 10240 65535
net.ipv4.tcp_keepalive_time = 30
net.ipv4.tcp_keepalive_intvl = 5
net.ipv4.tcp_keepalive_probes = 5
EOF_SYSCTL

sysctl --system >/dev/null 2>&1 || true

# ─── [3/8] Update Router Templates (HAProxy & Nginx Real-IP Multiplexer) ──────
echo "[3/8] Updating HAProxy & Nginx edge router templates..."
mkdir -p /opt/alyan/templates /var/www/alyan-acme /opt/alyan/bin /opt/alyan/services/xray-bridge

cat <<'EOF_HAPROXY_TPL' > /opt/alyan/templates/haproxy.cfg.tpl
# ═════════════════════════════════════════════════════════════════════════════
#  🔥 ALYAN WEBPANEL — HAProxy Flame Router (Ports 80 & 443 Wire-Speed Mux)
#  Auto-generated by alyan-ctl · Domain: {{DOMAIN}}
#  SSH Direct + SSH-SSL + SSH-WS (/alyan) + Xray (VLESS/VMess/Trojan) + ACME
# ═════════════════════════════════════════════════════════════════════════════
global
    log /dev/log local0 warning
    chroot /var/lib/haproxy
    stats socket /run/haproxy/admin.sock mode 660 level admin expose-fd listeners
    stats timeout 30s
    user haproxy
    group haproxy
    daemon
    maxconn 65535
    tune.bufsize 65536
    tune.maxrewrite 8192
    tune.ssl.cachesize 100000
    tune.ssl.lifetime 600
    tune.ssl.default-dh-param 2048
    ssl-default-bind-options ssl-min-ver TLSv1.2
    ssl-default-bind-ciphers ECDHE-ECDSA-AES128-GCM-SHA256:ECDHE-RSA-AES128-GCM-SHA256:ECDHE-ECDSA-AES256-GCM-SHA384:ECDHE-RSA-AES256-GCM-SHA384:ECDHE-ECDSA-CHACHA20-POLY1305:ECDHE-RSA-AES256-GCM-SHA384

defaults
    log     global
    mode    tcp
    option  dontlognull
    option  clitcpka
    option  srvtcpka
    option  abortonclose
    timeout connect 5s
    timeout client  4h
    timeout server  4h
    timeout tunnel  12h
    timeout client-fin 500ms
    timeout server-fin 500ms
    timeout http-keep-alive 4s

# ─── PUBLIC PORT 80: HTTP / SSH-WS (/alyan) / Xray WS / ACME ─────────────────
frontend fe_http_80
    bind *:80
    mode tcp
    tcp-request inspect-delay 1s

    acl is_raw_ssh    payload(0,4) -m bin 5353482d
    acl is_acme       req.payload(0,0) -m sub /.well-known/acme-challenge/
    acl is_xray       req.payload(0,0) -m sub -i /alyan-vless /alyan-vmess /alyan-trojan /alyan-xhttp alyan-vless-grpc
    acl is_http_80    payload(0,8) -m beg GET POST HEAD PUT OPTIONS CONNECT PATCH

    tcp-request content accept if is_raw_ssh or is_acme or is_xray or is_http_80

    use_backend be_dropbear  if is_raw_ssh
    use_backend be_nginx_ws  if is_acme or is_xray
    default_backend be_alyan_wsd

# ─── PUBLIC PORT 443 EDGE: Raw SSH vs TLS Multiplexer ────────────────────────
frontend fe_edge_443
    bind *:443
    mode tcp
    tcp-request inspect-delay 1s

    acl is_raw_ssh  payload(0,4) -m bin 5353482d
    acl is_tls      req.ssl_hello_type 1

    tcp-request content accept if is_raw_ssh or is_tls

    use_backend be_dropbear      if is_raw_ssh
    default_backend be_tls_loop

backend be_tls_loop
    mode tcp
    server tls_term 127.0.0.1:4443 send-proxy-v2

# ─── INTERNAL TLS TERMINATOR & SSH-SSL / SSH-WS / XRAY DISPATCHER ────────────
frontend fe_tls_terminator
    bind 127.0.0.1:4443 accept-proxy ssl crt /etc/alyan/ssl/haproxy.pem alpn http/1.1
    mode tcp
    tcp-request inspect-delay 1s

    acl is_ssh_ssl    payload(0,4) -m bin 5353482d
    acl is_xray       req.payload(0,0) -m sub -i /alyan-vless /alyan-vmess /alyan-trojan /alyan-xhttp alyan-vless-grpc
    acl is_http_req   payload(0,8) -m beg GET POST HEAD PUT OPTIONS CONNECT PATCH

    tcp-request content accept if is_ssh_ssl or is_xray or is_http_req

    use_backend be_dropbear        if is_ssh_ssl
    use_backend be_nginx_ws        if is_xray
    default_backend be_alyan_wsd

# ─── BACKENDS ────────────────────────────────────────────────────────────────
backend be_alyan_wsd
    mode tcp
    server wsd 127.0.0.1:2095 send-proxy-v2

backend be_dropbear
    mode tcp
    server dropbear 127.0.0.1:109

backend be_nginx_ws
    mode tcp
    server nginx_ws 127.0.0.1:8880 send-proxy-v2

EOF_HAPROXY_TPL

cat <<'EOF_NGINX_ROUTER_TPL' > /opt/alyan/templates/nginx-router.conf.tpl
# ═════════════════════════════════════════════════════════════════════════════
#  🔥 ALYAN WEBPANEL — Edge Router & Real-IP Multiplexer (Nginx)
# ═════════════════════════════════════════════════════════════════════════════
map $http_cf_connecting_ip $client_real_ip {
    "" $proxy_protocol_addr;
    default $http_cf_connecting_ip;
}

server {
    listen 127.0.0.1:8880 proxy_protocol backlog=4096;
    listen 127.0.0.1:8884 backlog=4096;
    server_name {{DOMAIN}} _;

    access_log off;
    reset_timedout_connection on;

    set_real_ip_from 127.0.0.1;
    real_ip_header proxy_protocol;

    location ^~ /.well-known/acme-challenge/ {
        root /var/www/alyan-acme;
        default_type "text/plain";
    }

    # ─── Xray VLESS WebSocket (via Alyan Real-Time Socket Bridge) ─────────────
    location /alyan-vless {
        proxy_pass http://127.0.0.1:8885;
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $client_real_ip;
        proxy_set_header X-Forwarded-For $client_real_ip;
        proxy_set_header CF-Connecting-IP $client_real_ip;
        proxy_read_timeout 86400s;
        proxy_send_timeout 86400s;
        proxy_buffering off;
        proxy_ignore_client_abort off;
    }

    # ─── Xray VMess WebSocket (via Alyan Real-Time Socket Bridge) ─────────────
    location /alyan-vmess {
        proxy_pass http://127.0.0.1:8885;
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $client_real_ip;
        proxy_set_header X-Forwarded-For $client_real_ip;
        proxy_set_header CF-Connecting-IP $client_real_ip;
        proxy_read_timeout 86400s;
        proxy_send_timeout 86400s;
        proxy_buffering off;
        proxy_ignore_client_abort off;
    }

    # ─── Xray Trojan WebSocket (via Alyan Real-Time Socket Bridge) ────────────
    location /alyan-trojan {
        proxy_pass http://127.0.0.1:8885;
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $client_real_ip;
        proxy_set_header X-Forwarded-For $client_real_ip;
        proxy_set_header CF-Connecting-IP $client_real_ip;
        proxy_read_timeout 86400s;
        proxy_send_timeout 86400s;
        proxy_buffering off;
        proxy_ignore_client_abort off;
    }

    # ─── Xray VLESS XHTTP (via Alyan Real-Time Socket Bridge) ─────────────────
    location /alyan-xhttp {
        proxy_pass http://127.0.0.1:8885;
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $client_real_ip;
        proxy_set_header X-Forwarded-For $client_real_ip;
        proxy_set_header CF-Connecting-IP $client_real_ip;
        proxy_buffering off;
        proxy_request_buffering off;
        proxy_read_timeout 86400s;
        proxy_send_timeout 86400s;
    }

    # ─── Xray VLESS gRPC ─────────────────────────────────────────────────────
    location /alyan-vless-grpc {
        grpc_pass grpc://127.0.0.1:20005;
        grpc_set_header X-Real-IP $client_real_ip;
        grpc_set_header X-Forwarded-For $client_real_ip;
        grpc_set_header CF-Connecting-IP $client_real_ip;
        grpc_read_timeout 86400s;
        grpc_send_timeout 86400s;
    }

    location / {
        default_type text/html;
        return 200 '<!DOCTYPE html><html><head><title>{{DOMAIN}}</title></head><body style="background:#050507;color:#f5f2ee;font-family:sans-serif;display:grid;place-items:center;height:100vh;margin:0"><div><h2 style="letter-spacing:.16em">🔥 ALYAN EDGE NODE ONLINE</h2></div></body></html>';
    }
}

EOF_NGINX_ROUTER_TPL

python3 - <<'EOF_RENDER_ROUTERS'
import sqlite3
from pathlib import Path

domain = "localhost"
db_p = Path("/var/lib/alyan/alyan.db")
if db_p.exists():
    try:
        conn = sqlite3.connect(str(db_p))
        row = conn.execute("SELECT value FROM settings WHERE key='domain'").fetchone()
        if row and row[0]:
            domain = str(row[0]).strip()
        conn.close()
    except Exception:
        pass

# Render Nginx router
nginx_tpl = Path("/opt/alyan/templates/nginx-router.conf.tpl").read_text()
Path("/etc/nginx/conf.d/alyan-router.conf").write_text(nginx_tpl.replace("{{DOMAIN}}", domain))

# Render HAProxy
hap_tpl = Path("/opt/alyan/templates/haproxy.cfg.tpl").read_text()
Path("/etc/haproxy/haproxy.cfg").write_text(hap_tpl.replace("{{DOMAIN}}", domain))
EOF_RENDER_ROUTERS

# ─── [4/8] Update Xray Core Multi-Protocol Engine Template ───────────────────
echo "[4/8] Updating Xray Core Multi-Engine template (20001-20005)..."
cat <<'EOF_XRAY_TPL' > /opt/alyan/templates/xray-config.json.tpl
{
  "log": {
    "loglevel": "warning",
    "access": "/var/log/xray/access.log",
    "error": "/var/log/xray/error.log"
  },
  "api": {
    "tag": "api",
    "services": [
      "StatsService"
    ]
  },
  "stats": {},
  "policy": {
    "levels": {
      "0": {
        "statsUserUplink": true,
        "statsUserDownlink": true,
        "connIdle": 30,
        "bufferSize": 1024,
        "uplinkOnly": 15,
        "downlinkOnly": 30,
        "handshake": 10
      }
    },
    "system": {
      "statsInboundUplink": true,
      "statsInboundDownlink": true
    }
  },
  "inbounds": [
    {
      "tag": "api",
      "port": 10085,
      "listen": "127.0.0.1",
      "protocol": "dokodemo-door",
      "settings": {
        "address": "127.0.0.1"
      }
    },
    {
      "tag": "vless-ws",
      "port": 20001,
      "listen": "127.0.0.1",
      "protocol": "vless",
      "settings": {
        "clients": {{VLESS_CLIENTS}},
        "decryption": "none"
      },
      "streamSettings": {
        "network": "ws",
        "wsSettings": {
          "path": "/alyan-vless",
          "heartbeatPeriod": 2
        },
        "sockopt": {
          "trustedXForwardedFor": ["CF-Connecting-IP", "X-Forwarded-For", "X-Real-IP"]
        }
      }
    },
    {
      "tag": "vmess-ws",
      "port": 20002,
      "listen": "127.0.0.1",
      "protocol": "vmess",
      "settings": {
        "clients": {{VMESS_CLIENTS}}
      },
      "streamSettings": {
        "network": "ws",
        "wsSettings": {
          "path": "/alyan-vmess",
          "heartbeatPeriod": 2
        },
        "sockopt": {
          "trustedXForwardedFor": ["CF-Connecting-IP", "X-Forwarded-For", "X-Real-IP"]
        }
      }
    },
    {
      "tag": "trojan-ws",
      "port": 20003,
      "listen": "127.0.0.1",
      "protocol": "trojan",
      "settings": {
        "clients": {{TROJAN_CLIENTS}}
      },
      "streamSettings": {
        "network": "ws",
        "wsSettings": {
          "path": "/alyan-trojan",
          "heartbeatPeriod": 2
        },
        "sockopt": {
          "trustedXForwardedFor": ["CF-Connecting-IP", "X-Forwarded-For", "X-Real-IP"]
        }
      }
    },
    {
      "tag": "vless-xhttp",
      "port": 20004,
      "listen": "127.0.0.1",
      "protocol": "vless",
      "settings": {
        "clients": {{VLESS_CLIENTS}},
        "decryption": "none"
      },
      "streamSettings": {
        "network": "xhttp",
        "xhttpSettings": {
          "path": "/alyan-xhttp",
          "mode": "stream-up"
        },
        "sockopt": {
          "trustedXForwardedFor": ["CF-Connecting-IP", "X-Forwarded-For", "X-Real-IP"]
        }
      }
    },
    {
      "tag": "vless-grpc",
      "port": 20005,
      "listen": "127.0.0.1",
      "protocol": "vless",
      "settings": {
        "clients": {{VLESS_CLIENTS}},
        "decryption": "none"
      },
      "streamSettings": {
        "network": "grpc",
        "grpcSettings": {
          "serviceName": "alyan-vless-grpc"
        }
      }
    }
  ],
  "outbounds": [
    {
      "protocol": "freedom",
      "tag": "direct"
    },
    {
      "protocol": "blackhole",
      "tag": "blocked"
    }
  ],
  "routing": {
    "domainStrategy": "AsIs",
    "rules": [
      {
        "type": "field",
        "inboundTag": ["api"],
        "outboundTag": "api"
      }
    ]
  }
}

EOF_XRAY_TPL

# ─── [5/8] Deploy Alyan Xray Real-Time Socket Bridge ─────────────────────────
echo "[5/8] Deploying Alyan Xray Real-Time Socket Bridge (127.0.0.1:8885)..."
if [[ -f "./services/xray-bridge/alyan-xray-bridge" ]]; then
    cp "./services/xray-bridge/alyan-xray-bridge" /opt/alyan/bin/alyan-xray-bridge
elif [[ -f "/opt/alyan/services/xray-bridge/alyan-xray-bridge" ]]; then
    cp "/opt/alyan/services/xray-bridge/alyan-xray-bridge" /opt/alyan/bin/alyan-xray-bridge
else
    base64 -d <<'EOF_BRIDGE_B64' | gzip -d > /opt/alyan/bin/alyan-xray-bridge
